@dataclass(frozen=True, slots=True)
class Event:
    id: int
    eventid: str
    source: str
    displaypath: str
    priority: int
    eventtype: int
    eventflags: int
    eventtime: datetime

    @property
    def is_system(self) -> bool:
        return bool(self.eventflags & FLAG_SYSTEM)

    @property
    def is_shelved(self) -> bool:
        return bool(self.eventflags & FLAG_SHELVED)

